import{_ as t,o as r,c as s,a0 as n}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"Prerequisites","description":"What the machine needs before the first start of the control plane.","frontmatter":{"title":"Prerequisites","description":"What the machine needs before the first start of the control plane."},"headers":[],"relativePath":"getting-started/prerequisites.md","filePath":"getting-started/prerequisites.md"}'),a={name:"getting-started/prerequisites.md"};function o(i,e,h,l,d,c){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><p>The control plane ships through npm. You install nothing: <code>npx</code> runs the current published version. Before the first start, the machine needs:</p><ul><li>Bun <code>1.3.0</code> or newer. The control plane runs on Bun. Below the floor the start fails with the required version and the reason: the OpenTUI renderer uses Bun&#39;s stable FFI, and the bin gates the version before it loads the native core.</li><li>Node, for the <code>npx</code> that bootstraps the launcher. The launcher finds Bun on the <code>PATH</code> and hands it the app, so both runtimes are needed for the <code>npx</code> commands; a global install runs the app on Bun alone.</li><li><a href="https://github.com/seriousjul/herdr" target="_blank" rel="noreferrer">herdr</a> on the <code>PATH</code>. The control plane drives it through its CLI and never starts an agent process itself.</li><li>The agent CLI of each agent type you use, with its own provider auth applied.</li></ul><p>Next: <a href="./first-launch.html">first launch</a>.</p>',4)])])}const f=t(a,[["render",o]]);export{u as __pageData,f as default};
